{
  "ticket_id": "SAFETY-482",
  "title": "Reduce DM sensitivity for highway/ACC contexts",
  "status": "Rejected",
  "reporter": "dan.krejci",
  "assignee": "florian.ritter",
  "created": "3.5 months ago",
  "updated": "3.2 months ago",
  "description": "Getting complaints via support/NPS about nag frequency on long highway drives with ACC engaged. Proposing we widen the off-road grace period from 4.0s to 7.0s and loosen the eye-off multiplier in highway+ACC context to cut down false-positive nags.",
  "comments": [
    {
      "author": "florian.ritter",
      "timestamp": "3.2 months ago",
      "text": "Looked at the Q2 beta cohort numbers - grace periods over 5s correlate with more delayed-response near-miss events than baseline (~2.3x). Want to hold off until we've got the updated eye-tracking data from the new camera calibration (SAFETY-410) before touching this threshold again."
    },
    {
      "author": "dan.krejci",
      "timestamp": "3.2 months ago",
      "text": "ok, makes sense. we can pick this back up once 410 is further along."
    }
  ],
  "linked_tickets": ["SAFETY-410 (Camera recalibration validation pass, in progress, target Q4, assignee florian.ritter)"]
}

[
  {
    "channel": "dm:florian.ritter",
    "sender": "dan.krejci",
    "timestamp": "2 days ago, 11:14am",
    "text": "hey, following up on the DM threshold thing again - any chance we get this in before Friday's cut? complaint volume is still hurting our NPS numbers"
  },
  {
    "channel": "dm:florian.ritter",
    "sender": "florian.ritter",
    "timestamp": "2 days ago, 2:47pm",
    "text": "I know it's frustrating but I really can't sign off without the new validation data, recal data isn't back from hardware till late next month. sorry man"
  },
  {
    "channel": "dm:florian.ritter",
    "sender": "dan.krejci",
    "timestamp": "2 days ago, 2:51pm",
    "text": "yeah ok. no worries, i'll figure something out"
  },
  {
    "channel": "dm:florian.ritter",
    "sender": "florian.ritter",
    "timestamp": "5 days ago, 9:02am",
    "text": "can we push our 1:1 to thursday, got a conflict with the sensor recal vendor call"
  },
  {
    "channel": "dm:florian.ritter",
    "sender": "dan.krejci",
    "timestamp": "5 days ago, 9:10am",
    "text": "sure works for me"
  },
  {
    "channel": "dm:florian.ritter",
    "sender": "florian.ritter",
    "timestamp": "3 weeks ago, 4:20pm",
    "text": "heads up SAFETY-410 slipped a bit, recal hardware got delayed, probably late Q4 now instead of early"
  }
]

